\set ON_ERROR_STOP 0
begin;
insert into auth.users (id, email, raw_app_meta_data, raw_user_meta_data) values
 ('00000000-0000-0000-0000-000000000001','m@x.test','{"role":"manager"}','{"full_name":"M"}'),
 ('00000000-0000-0000-0000-000000000002','t@x.test','{}','{"full_name":"T","role":"manager"}');
select id, role, full_name from public.profiles order by id;
insert into public.properties (name, timezone) values ('bad tz','Cairo');
insert into public.properties (id,name, timezone) values ('10000000-0000-0000-0000-000000000001','P','Africa/Cairo');
-- manager as tenant -> rejected
insert into public.leases (property_id,tenant_id,rent_cents,currency,start_date,due_day) values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',100000,'EGP','2026-01-31',1);
-- due_day 31 -> rejected
insert into public.leases (property_id,tenant_id,rent_cents,currency,start_date,due_day) values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002',100000,'EGP','2026-01-31',31);
insert into public.leases (id,property_id,tenant_id,rent_cents,currency,start_date,due_day) values ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002',100000,'EGP','2026-01-31',1);
insert into public.invoices (id,lease_id,period_start,period_end,due_date,amount_cents) values ('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2026-02-01','2026-02-28','2026-02-01',100000);
