insert into public.invoices (lease_id,period_start,period_end,due_date,amount_cents) values ('20000000-0000-0000-0000-000000000001','2026-02-01','2026-02-28','2026-02-01',100000);
-- overpaid -> rejected ; status mismatch -> rejected
update public.invoices set paid_cents=100001, status='paid';
update public.invoices set paid_cents=500, status='paid';
update public.invoices set paid_cents=500, status='partial' returning status, paid_cents;
-- online without provider -> rejected
insert into public.payments (invoice_id,method,amount_cents,idempotency_key) values ('30000000-0000-0000-0000-000000000001','online',500,'k1');
insert into public.payments (invoice_id,method,amount_cents,idempotency_key) values ('30000000-0000-0000-0000-000000000001','cash',500,'k1');
-- same idempotency key -> rejected
insert into public.payments (invoice_id,method,amount_cents,idempotency_key) values ('30000000-0000-0000-0000-000000000001','cash',500,'k1');
insert into public.webhook_events (provider,event_id,payload) values ('stripe','evt_1','{}') on conflict (provider,event_id) do nothing;
insert into public.webhook_events (provider,event_id,payload) values ('stripe','evt_1','{}') on conflict (provider,event_id) do nothing;
rollback;
SQL
