  provider = "prisma-client"
  output   = "../generated/prisma"
}

datasource db {
  provider = "postgresql"
  schemas  = ["auth", "public"]
}

-- Each block runs in its own transaction and rolls back; prints OK when the DB rejected as expected.
\set ON_ERROR_STOP 0
create or replace function pg_temp.expect_fail(label text, stmt text) returns void language plpgsql as $$
begin
  execute stmt;
  raise notice 'FAIL (accepted): %', label;
exception when others then
  raise notice 'OK  % -> %', label, sqlerrm;
end $$;
create or replace function pg_temp.expect_ok(label text, stmt text) returns void language plpgsql as $$
begin
  execute stmt;
  raise notice 'OK  % -> accepted', label;
exception when others then
  raise notice 'FAIL (rejected): % -> %', label, sqlerrm;
end $$;

begin;
select pg_temp.expect_fail('overlapping lease (start = existing end)', $q$insert into leases (org_id, unit_id, tenant_id, start_date, end_date, monthly_rent_sen, deposit_sen) values ('00000000-0000-0000-0000-0000000000a1','11111111-0000-0000-0000-000000000001','33333333-0000-0000-0000-000000000001','2026-03-31','2026-06-30',1,0)$q$);
select pg_temp.expect_ok('adjacent lease (start = existing end + 1)', $q$insert into leases (org_id, unit_id, tenant_id, start_date, end_date, monthly_rent_sen, deposit_sen) values ('00000000-0000-0000-0000-0000000000a1','11111111-0000-0000-0000-000000000001','33333333-0000-0000-0000-000000000001','2026-04-01','2026-06-30',1,0)$q$);
select pg_temp.expect_fail('lease on other org unit', $q$insert into leases (org_id, unit_id, tenant_id, start_date, end_date, monthly_rent_sen, deposit_sen) values ('00000000-0000-0000-0000-0000000000a1','22222222-0000-0000-0000-000000000001','33333333-0000-0000-0000-000000000001','2027-01-01','2027-02-01',1,0)$q$);
select pg_temp.expect_fail('lease for other org tenant', $q$insert into leases (org_id, unit_id, tenant_id, start_date, end_date, monthly_rent_sen, deposit_sen) values ('00000000-0000-0000-0000-0000000000a1','11111111-0000-0000-0000-000000000003','44444444-0000-0000-0000-000000000001','2027-01-01','2027-02-01',1,0)$q$);
select pg_temp.expect_fail('two deposits on one lease', $q$insert into invoices (org_id, lease_id, kind, due_date, amount_sen) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000002','deposit','2026-01-01',1),('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000002','deposit','2026-01-01',1)$q$);
select pg_temp.expect_fail('rent invoice without period', $q$insert into invoices (org_id, lease_id, kind, due_date, amount_sen) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000002','rent','2026-01-01',1)$q$);
select pg_temp.expect_fail('bank transfer without slip', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001',1,'bank_transfer','approved',now())$q$);
select pg_temp.expect_fail('slip in other org folder', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at, slip_path) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001',1,'bank_transfer','approved',now(),'00000000-0000-0000-0000-0000000000b2/x.pdf')$q$);
select pg_temp.expect_fail('slip file that does not exist', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at, slip_path) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001',1,'bank_transfer','approved',now(),'00000000-0000-0000-0000-0000000000a1/missing.pdf')$q$);
select pg_temp.expect_fail('cash with unapplied_sen', $q$insert into payments (org_id, lease_id, amount_sen, unapplied_sen, method, status, received_at) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001',5,1,'cash','approved',now())$q$);
select pg_temp.expect_fail('online payment for a bill of another lease', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at, gateway_bill_id) select '00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000002',1,'online','approved',now(), id from gateway_bills limit 1$q$);
select pg_temp.expect_ok('first online payment for the bill', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at, gateway_bill_id) select org_id, lease_id, amount_sen,'online','approved',now(), id from gateway_bills limit 1$q$);
select pg_temp.expect_fail('second online payment for the same bill', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at, gateway_bill_id) select org_id, lease_id, amount_sen,'online','approved',now(), id from gateway_bills limit 1$q$);
select pg_temp.expect_fail('allocation above invoice amount', $q$insert into payment_allocations (org_id, lease_id, payment_id, invoice_id, amount_sen) select '00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001', id, '77777777-0000-0000-0000-000000000001', 40001 from payments where method='online'$q$);
select pg_temp.expect_fail('allocation for a pending payment', $q$insert into payment_allocations (org_id, lease_id, payment_id, invoice_id, amount_sen) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001','99999999-0000-0000-0000-000000000002','77777777-0000-0000-0000-000000000001',1)$q$);
select pg_temp.expect_fail('allocation to another lease invoice', $q$insert into payment_allocations (org_id, lease_id, payment_id, invoice_id, amount_sen) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001','99999999-0000-0000-0000-000000000001','77777777-0000-0000-0000-000000000002',1)$q$);
select pg_temp.expect_fail('delete a payment', $q$delete from payments where id='99999999-0000-0000-0000-000000000001'$q$);
select pg_temp.expect_fail('approved -> pending', $q$update payments set status='pending_verification' where id='99999999-0000-0000-0000-000000000001'$q$);
select pg_temp.expect_fail('change payment amount', $q$update payments set amount_sen=1 where id='99999999-0000-0000-0000-000000000001'$q$);
select pg_temp.expect_fail('reject with 4-char reason', $q$update payments set status='rejected', reason=' abcd ' where id='99999999-0000-0000-0000-000000000002'$q$);
select pg_temp.expect_ok('reject with 5-char reason', $q$update payments set status='rejected', reason='abcde' where id='99999999-0000-0000-0000-000000000002'$q$);
select pg_temp.expect_fail('bad tenant phone', $q$update tenants set phone='call me' where id='33333333-0000-0000-0000-000000000001'$q$);
select pg_temp.expect_fail('audit_log update as postgres', $q$update audit_log set action='x'$q$);
select pg_temp.expect_fail('audit_log delete as postgres', $q$delete from audit_log$q$);
select pg_temp.expect_fail('audit_log truncate as postgres', $q$truncate audit_log$q$);
rollback;

begin;
set local role service_role;
select pg_temp.expect_fail('audit_log delete as service_role', $q$delete from audit_log$q$);
select pg_temp.expect_fail('payments insert as service_role', $q$insert into payments (org_id, lease_id, amount_sen, method, status, received_at) values ('00000000-0000-0000-0000-0000000000a1','55555555-0000-0000-0000-000000000001',1,'cash','approved',now())$q$);
rollback;

begin;
set local role supabase_admin;
select pg_temp.expect_fail('audit_log delete as supabase_admin (superuser)', $q$delete from audit_log$q$);
rollback;

select 'bill id: ' || id as sample from gateway_bills;

