import 'server-only'
import { NextResponse } from 'next/server'
import { HttpError, badRequest } from '@/lib/errors'

/** Errors -> `{ error }` JSON responses. Unknown errors become a bare 500 (details only in server logs). */
export async function handle(fn: () => Promise<Response>): Promise<Response> {
  try {
    return await fn()
  } catch (error) {
    if (error instanceof HttpError) {
      return NextResponse.json({ error: error.message }, { status: error.status })
    }
    console.error('Unhandled API error:', error instanceof Error ? error.message : 'unknown error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/** Parses a JSON request body; malformed JSON is a 400 (raised when the service validates it). */
export async function readJson(req: Request): Promise<unknown> {
  try {
    return await req.json()
  } catch {
    return INVALID_JSON
  }
}

// Sentinel so services can reject a bad body only AFTER the 404/403 checks.
export const INVALID_JSON = Symbol('invalid-json')

export function assertJson(body: unknown): void {
  if (body === INVALID_JSON) throw badRequest('Request body must be valid JSON')
}

