/**
 * Who is calling. Role and org come ONLY from our tables (memberships, or
 * tenants.user_id), never from user_metadata or the request.
 */
export type Actor =
  | { kind: 'member'; userId: string; orgId: string; role: 'manager' | 'staff' }
  | { kind: 'tenant'; userId: string; orgId: string; tenantId: string }
  // Valid login but no membership and no tenant row: sees nothing.
  | { kind: 'none'; userId: string }

/**
 * Authenticates the request: `Authorization: Bearer <access token>` if
 * present (it wins over the cookie), otherwise the session cookie. Both are
 * verified with the Auth server via getUser(), never getSession().
 * Throws 401 when there's no valid login.
 */
export async function getActor(req?: Request): Promise<Actor> {
  const userId = await authenticatedUserId(req)
  if (!userId) throw unauthorized()
  return loadActor(userId)
}

async function authenticatedUserId(req?: Request): Promise<string | null> {
  const header = req?.headers.get('authorization')
  if (header) {
    const match = /^Bearer\s+(\S+)$/i.exec(header)
    if (!match) return null
    const supabase = createSupabaseClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
