    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/** Parses a JSON request body; malformed JSON is a 400 (raised when the service validates it). */
export async function readJson(req: Request): Promise<unknown> {
  try {
    return await req.json()
  } catch {
    return INVALID_JSON
  }
}

// Sentinel so services can reject a bad body only AFTER the 404/403 checks.
export const INVALID_JSON = Symbol('invalid-json')

export function assertJson(body: unknown): void {
  if (body === INVALID_JSON) throw badRequest('Request body must be valid JSON')
}

