import 'server-only'
import { PrismaPg } from '@prisma/adapter-pg'
import { PrismaClient } from '@/generated/prisma/client'

// Prisma connects as the database owner and BYPASSES RLS.
// Every query must be scoped by the caller's org/tenant in our services.

const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient }

function createPrismaClient(): PrismaClient {
  const connectionString = process.env.DATABASE_URL
  if (!connectionString) throw new Error('DATABASE_URL is not set')
  return new PrismaClient({ adapter: new PrismaPg({ connectionString }) })
}

// One client per process (Next dev hot reload would otherwise open new pools).
export const prisma = globalForPrisma.prisma ?? createPrismaClient()
if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma

export type Tx = Parameters<Parameters<PrismaClient['$transaction']>[0]>[0]

import type { Tx } from '@/lib/prisma'

// Money bookkeeping for one lease. Every function here must run inside a
// transaction that has called lockLease() first: the lease row lock is what
// serializes concurrent payments / approvals / voids / webhooks on a lease, so
// the balances read below can't change until we commit.

/** Locks the lease row until the transaction ends. Always lock the lease FIRST (no deadlocks). */
export async function lockLease(tx: Tx, leaseId: string): Promise<void> {
  await tx.$queryRaw`SELECT id FROM public.leases WHERE id = ${leaseId}::uuid FOR UPDATE`
}

export interface LeaseBalances {
  totalSen: bigint // sum of all invoices
  allocatedSen: bigint // sum of all allocations (approved payments)
  pendingSen: bigint // sum of payments still pending_verification
}

export async function leaseBalances(tx: Tx, leaseId: string): Promise<LeaseBalances> {
  // ::bigint because sum(bigint) returns numeric.
  const [row] = await tx.$queryRaw<Array<{ total: bigint; allocated: bigint; pending: bigint }>>`
    SELECT
      (SELECT coalesce(sum(amount_sen), 0) FROM public.invoices WHERE lease_id = ${leaseId}::uuid)::bigint AS total,
      (SELECT coalesce(sum(amount_sen), 0) FROM public.payment_allocations WHERE lease_id = ${leaseId}::uuid)::bigint AS allocated,
      (SELECT coalesce(sum(amount_sen), 0) FROM public.payments
        WHERE lease_id = ${leaseId}::uuid AND status = 'pending_verification')::bigint AS pending`
  return { totalSen: row.total, allocatedSen: row.allocated, pendingSen: row.pending }
}

export interface InvoiceWithPaid {
  id: string
  kind: 'deposit' | 'rent'
  period_index: number | null
  period_start: Date | null
  period_end: Date | null
  due_date: Date
  amount_sen: bigint
  paid_sen: bigint
}

/**
 * A lease's invoices with what's been allocated to each, in allocation order:
 * due date, then deposit before rent, then period index (SPEC section 4).
 */
export async function invoicesInAllocationOrder(tx: Tx, leaseId: string): Promise<InvoiceWithPaid[]> {
  return tx.$queryRaw<InvoiceWithPaid[]>`
    SELECT i.id, i.kind::text AS kind, i.period_index, i.period_start, i.period_end, i.due_date, i.amount_sen,
           coalesce(sum(a.amount_sen), 0)::bigint AS paid_sen
    FROM public.invoices i
    LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
    WHERE i.lease_id = ${leaseId}::uuid
    GROUP BY i.id
    ORDER BY i.due_date, (i.kind = 'rent'), i.period_index NULLS FIRST`
}

/**
 * Allocates an approved payment to the lease's unpaid invoices in allocation
 * order, filling each before the next (not-yet-due ones included). Whatever
 * is left goes to payments.unapplied_sen.
 */
export async function allocatePayment(
  tx: Tx,
  payment: { id: string; org_id: string; lease_id: string; amount_sen: bigint },
): Promise<void> {
  let remaining = payment.amount_sen
  const allocations: Array<{ invoice_id: string; amount_sen: bigint }> = []

  for (const invoice of await invoicesInAllocationOrder(tx, payment.lease_id)) {
    if (remaining === 0n) break
    const unpaid = invoice.amount_sen - invoice.paid_sen
    if (unpaid <= 0n) continue
    const take = unpaid < remaining ? unpaid : remaining
    allocations.push({ invoice_id: invoice.id, amount_sen: take })
    remaining -= take
  }

  if (allocations.length > 0) {
    await tx.payment_allocations.createMany({
      data: allocations.map((a) => ({
        org_id: payment.org_id,
        lease_id: payment.lease_id,
        payment_id: payment.id,
        invoice_id: a.invoice_id,
        amount_sen: a.amount_sen,
      })),
    })
  }
  await tx.payments.update({ where: { id: payment.id }, data: { unapplied_sen: remaining } })
}

export async function writeAudit(
  tx: Tx,
  entry: { orgId: string; actorId: string | null; action: string; entityId: string; details?: Record<string, unknown> },
): Promise<void> {
  await tx.audit_log.create({
    data: {
      org_id: entry.orgId,
      actor_id: entry.actorId,
      action: entry.action,
      entity_id: entry.entityId,
      details: (entry.details ?? {}) as object,
    },
  })
}

import type { Db, Tx } from '@/lib/prisma'

// Money bookkeeping for one lease. Every function here must run inside a
// transaction that has called lockLease() first: the lease row lock is what
// serializes concurrent payments / approvals / voids / webhooks on a lease, so
// the balances read below can't change until we commit.

/** Locks the lease row until the transaction ends. Always lock the lease FIRST (no deadlocks). */
export async function lockLease(tx: Tx, leaseId: string): Promise<void> {
  await tx.$queryRaw`SELECT id FROM public.leases WHERE id = ${leaseId}::uuid FOR UPDATE`
}

export interface LeaseBalances {
  totalSen: bigint // sum of all invoices
  allocatedSen: bigint // sum of all allocations (approved payments)
  pendingSen: bigint // sum of payments still pending_verification
}

export async function leaseBalances(tx: Tx, leaseId: string): Promise<LeaseBalances> {
  // ::bigint because sum(bigint) returns numeric.
  const [row] = await tx.$queryRaw<Array<{ total: bigint; allocated: bigint; pending: bigint }>>`
    SELECT
      (SELECT coalesce(sum(amount_sen), 0) FROM public.invoices WHERE lease_id = ${leaseId}::uuid)::bigint AS total,
      (SELECT coalesce(sum(amount_sen), 0) FROM public.payment_allocations WHERE lease_id = ${leaseId}::uuid)::bigint AS allocated,
      (SELECT coalesce(sum(amount_sen), 0) FROM public.payments
        WHERE lease_id = ${leaseId}::uuid AND status = 'pending_verification')::bigint AS pending`
  return { totalSen: row.total, allocatedSen: row.allocated, pendingSen: row.pending }
}

export interface InvoiceWithPaid {
  id: string
  kind: 'deposit' | 'rent'
  period_index: number | null
  period_start: Date | null
  period_end: Date | null
  due_date: Date
  amount_sen: bigint
  paid_sen: bigint
}

/**
 * A lease's invoices with what's been allocated to each, in allocation order:
 * due date, then deposit before rent, then period index (SPEC section 4).
 */
export async function invoicesInAllocationOrder(tx: Tx, leaseId: string): Promise<InvoiceWithPaid[]> {
  return tx.$queryRaw<InvoiceWithPaid[]>`
    SELECT i.id, i.kind::text AS kind, i.period_index, i.period_start, i.period_end, i.due_date, i.amount_sen,
           coalesce(sum(a.amount_sen), 0)::bigint AS paid_sen
    FROM public.invoices i
    LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
    WHERE i.lease_id = ${leaseId}::uuid
    GROUP BY i.id
    ORDER BY i.due_date, (i.kind = 'rent'), i.period_index NULLS FIRST`
}

/**
 * Allocates an approved payment to the lease's unpaid invoices in allocation
 * order, filling each before the next (not-yet-due ones included). Whatever
 * is left goes to payments.unapplied_sen.
 */
export async function allocatePayment(
  tx: Tx,
  payment: { id: string; org_id: string; lease_id: string; amount_sen: bigint },
): Promise<void> {
  let remaining = payment.amount_sen
  const allocations: Array<{ invoice_id: string; amount_sen: bigint }> = []

  for (const invoice of await invoicesInAllocationOrder(tx, payment.lease_id)) {
    if (remaining === 0n) break
    const unpaid = invoice.amount_sen - invoice.paid_sen
    if (unpaid <= 0n) continue
    const take = unpaid < remaining ? unpaid : remaining
    allocations.push({ invoice_id: invoice.id, amount_sen: take })
    remaining -= take
  }

  if (allocations.length > 0) {
    await tx.payment_allocations.createMany({
      data: allocations.map((a) => ({
        org_id: payment.org_id,
        lease_id: payment.lease_id,
        payment_id: payment.id,
        invoice_id: a.invoice_id,
        amount_sen: a.amount_sen,
      })),
    })
  }
  await tx.payments.update({ where: { id: payment.id }, data: { unapplied_sen: remaining } })
}

export async function writeAudit(
  tx: Tx,
  entry: { orgId: string; actorId: string | null; action: string; entityId: string; details?: Record<string, unknown> },
): Promise<void> {
  await tx.audit_log.create({
    data: {
      org_id: entry.orgId,
      actor_id: entry.actorId,
      action: entry.action,
      entity_id: entry.entityId,
      details: (entry.details ?? {}) as object,
    },
  })
}

import { type Actor, requireRole } from '@/lib/actor'
import { generateSchedule, invoiceStatus, malaysiaToday, type InvoiceStatus } from '@/lib/billing'
import { fromDbDate, isUuid, toDbDate, toMalaysiaIso, toSen } from '@/lib/convert'
import { badRequest, conflict, forbidden, notFound, pgErrorCode, unprocessable } from '@/lib/errors'
import { invoicesInAllocationOrder, writeAudit } from '@/lib/ledger'
import { prisma, type Tx } from '@/lib/prisma'
import { createLeaseSchema, parseBody } from '@/lib/validation'

type Db = typeof prisma | Tx

/**
 * The lease if the actor may see it, else 404 (also for ids that don't exist
 * or aren't UUIDs, so the response never reveals another org's records).
 * Staff/managers: leases of their org. Tenants: their own leases.
 */
export async function findLeaseForActor(db: Db, actor: Actor, leaseId: string) {
  if (!isUuid(leaseId) || actor.kind === 'none') throw notFound()
  const lease = await db.leases.findFirst({
    where: actor.kind === 'member' ? { id: leaseId, org_id: actor.orgId } : { id: leaseId, tenant_id: actor.tenantId },
  })
  if (!lease) throw notFound()
  return lease
}

/** POST /api/leases: stores the lease and exactly generateSchedule's invoices, all or nothing. */
export async function createLease(actor: Actor, body: unknown): Promise<{ id: string }> {
  requireRole(actor, 'manager')
  const input = parseBody(createLeaseSchema, body)

  let schedule
  try {
    schedule = generateSchedule(input)
  } catch (error) {
    throw badRequest(error instanceof Error ? error.message : 'Invalid lease')
  }

  // Body ids are untrusted: the unit and tenant must be in the manager's own org.
  const [unit, tenant] = await Promise.all([
    prisma.units.findFirst({ where: { id: input.unitId, org_id: actor.orgId } }),
    prisma.tenants.findFirst({ where: { id: input.tenantId, org_id: actor.orgId } }),
  ])
  if (!unit || !tenant) throw notFound()

  try {
    return await prisma.$transaction(async (tx) => {
      const lease = await tx.leases.create({
        data: {
          org_id: actor.orgId,
          unit_id: unit.id,
          tenant_id: tenant.id,
          start_date: toDbDate(input.startDate),
          end_date: toDbDate(input.endDate),
          monthly_rent_sen: BigInt(input.monthlyRentSen),
          deposit_sen: BigInt(input.depositSen),
          created_by: actor.userId,
        },
      })
      await tx.invoices.createMany({
        data: schedule.map((invoice) => ({
          org_id: actor.orgId,
          lease_id: lease.id,
          kind: invoice.kind,
          period_index: invoice.periodIndex,
          period_start: invoice.periodStart === null ? null : toDbDate(invoice.periodStart),
          period_end: invoice.periodEnd === null ? null : toDbDate(invoice.periodEnd),
          due_date: toDbDate(invoice.dueDate),
          amount_sen: BigInt(invoice.amountSen),
        })),
      })
      await writeAudit(tx, {
        orgId: actor.orgId,
        actorId: actor.userId,
        action: 'lease.create',
        entityId: lease.id,
        details: { ...input, invoiceCount: schedule.length },
      })
      return { id: lease.id }
    })
  } catch (error) {
    // The exclusion constraint leases_no_overlap: also catches two concurrent creates.
    if (pgErrorCode(error) === '23P01') throw conflict('The lease overlaps another lease on this unit')
    throw error
  }
}

export interface LeaseDetail {
  lease: {
    id: string
    unitId: string
    tenantId: string
    startDate: string
    endDate: string
    monthlyRentSen: number
    depositSen: number
  }
  invoices: Array<{
    id: string
    kind: 'deposit' | 'rent'
    periodIndex: number | null
    periodStart: string | null
    periodEnd: string | null
    dueDate: string
    amountSen: number
    paidSen: number
    status: InvoiceStatus
  }>
  payments: Array<{
    id: string
    amountSen: number
    unappliedSen: number
    method: 'cash' | 'bank_transfer' | 'online'
    status: 'pending_verification' | 'approved' | 'rejected' | 'voided'
    receivedAt: string
  }>
}

/** GET /api/leases/:leaseId for staff, managers and the lease's tenant. */
export async function getLeaseDetail(actor: Actor, leaseId: string, now: Date): Promise<LeaseDetail> {
  const lease = await findLeaseForActor(prisma, actor, leaseId)

  const [invoices, payments] = await Promise.all([
    invoicesInAllocationOrder(prisma, lease.id),
    prisma.payments.findMany({ where: { lease_id: lease.id }, orderBy: [{ received_at: 'asc' }, { created_at: 'asc' }] }),
  ])

  return {
    lease: {
      id: lease.id,
      unitId: lease.unit_id,
      tenantId: lease.tenant_id,
      startDate: fromDbDate(lease.start_date),
      endDate: fromDbDate(lease.end_date),
      monthlyRentSen: toSen(lease.monthly_rent_sen),
      depositSen: toSen(lease.deposit_sen),
    },
    invoices: invoices.map((invoice) => {
      const dueDate = fromDbDate(invoice.due_date)
      const amountSen = toSen(invoice.amount_sen)
      const paidSen = toSen(invoice.paid_sen)
      return {
        id: invoice.id,
        kind: invoice.kind,
        periodIndex: invoice.period_index,
        periodStart: invoice.period_start && fromDbDate(invoice.period_start),
        periodEnd: invoice.period_end && fromDbDate(invoice.period_end),
        dueDate,
        amountSen,
        paidSen,
        status: invoiceStatus({ dueDate, amountSen, paidSen }, now),
      }
    }),
    payments: payments.map((payment) => ({
      id: payment.id,
      amountSen: toSen(payment.amount_sen),
      unappliedSen: toSen(payment.unapplied_sen),
      method: payment.method,
      status: payment.status,
      receivedAt: toMalaysiaIso(payment.received_at),
    })),
  }
}

/**
 * POST /api/leases/:leaseId/gateway-bills, for the lease's own tenant.
 * Amount = unpaid part of the invoices due on or before today (Malaysia).
 */
export async function createGatewayBill(actor: Actor, leaseId: string, now: Date) {
  const lease = await findLeaseForActor(prisma, actor, leaseId)
  // Visible to staff/managers too, but only the tenant can pay online.
  if (actor.kind !== 'tenant') throw forbidden()

  const today = malaysiaToday(now)
  const dueSen = (await invoicesInAllocationOrder(prisma, lease.id))
    .filter((invoice) => fromDbDate(invoice.due_date) <= today)
    .reduce((sum, invoice) => sum + (invoice.amount_sen - invoice.paid_sen), 0n)
  if (dueSen <= 0n) throw unprocessable('Nothing is due on this lease')

  const bill = await prisma.gateway_bills.create({
    data: { org_id: lease.org_id, lease_id: lease.id, amount_sen: dueSen, created_by: actor.userId },
  })
  return { billId: bill.id, amountSen: toSen(bill.amount_sen) }
}

