'use client'

import Link from 'next/link'
import { useState } from 'react'
import { toast } from 'sonner'
import { Button, buttonVariants } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { postJson } from '@/lib/api-client'
import { formatSen } from '@/lib/format'

export function PayNowButton({ leaseId, amountDueSen }: { leaseId: string; amountDueSen: number }) {
  const [bill, setBill] = useState<{ billId: string; amountSen: number } | null>(null)
  const [pending, setPending] = useState(false)

  async function payNow() {
    setPending(true)
    try {
      setBill(await postJson<{ billId: string; amountSen: number }>(`/api/leases/${leaseId}/gateway-bills`))
      toast.success('Payment bill created')
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Could not start the payment')
    } finally {
      setPending(false)
    }
  }

  return (
    <>
      <Button onClick={payNow} disabled={pending || amountDueSen <= 0}>
        {pending ? 'Creating bill…' : amountDueSen > 0 ? 'Pay now' : 'Nothing due'}
      </Button>
      <Dialog open={bill !== null} onOpenChange={(open) => !open && setBill(null)}>
        <DialogContent>
          {bill && (
            <>
              <DialogHeader>
                <DialogTitle>Online payment bill</DialogTitle>
                <DialogDescription>
                  In production you would now be sent to the payment gateway. The payment is only confirmed when the gateway
                  notifies us.
                </DialogDescription>
              </DialogHeader>
              <dl className="grid grid-cols-[6rem_1fr] gap-y-2 text-sm">
                <dt className="text-muted-foreground">Bill ID</dt>
                <dd className="break-all font-mono">{bill.billId}</dd>
                <dt className="text-muted-foreground">Amount</dt>
                <dd className="font-semibold tabular-nums">
                  {formatSen(bill.amountSen)} <span className="font-normal text-muted-foreground">({bill.amountSen} sen)</span>
                </dd>
              </dl>
              <DialogFooter>
                <Link
                  href={`/payments/return?bill_id=${encodeURIComponent(bill.billId)}`}
                  className={buttonVariants({ variant: 'default' })}
                >
                  Check payment status
                </Link>
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useRouter } from 'next/navigation'
import { useState, type FormEvent } from 'react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { createClient } from '@/lib/supabase/browser'

// Same rule as the tenants_phone_check constraint in the database.
const PHONE_PATTERN = /^\+?[0-9][0-9 -]{5,19}$/

/**
 * Updates the phone number straight from the browser through the Data API
 * (supabase-js + the tenant's session). RLS and the column grant only allow
 * a tenant to change the phone on their own row.
 */
export function PhoneForm({ tenantId, initialPhone }: { tenantId: string; initialPhone: string }) {
  const router = useRouter()
  const [phone, setPhone] = useState(initialPhone)
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  async function onSubmit(event: FormEvent) {
    event.preventDefault()
    const value = phone.trim()
    if (value && !PHONE_PATTERN.test(value)) {
      setError('Use digits, spaces or dashes, optionally starting with +, e.g. +60 12-345 6789.')
      return
    }
    setError(null)
    setPending(true)
    const { data, error: updateError } = await createClient()
      .from('tenants')
      .update({ phone: value || null })
      .eq('id', tenantId)
      .select('phone')
    setPending(false)
    if (updateError || !data || data.length !== 1) {
      toast.error('Could not update your phone number')
      return
    }
    toast.success('Phone number updated')
    router.refresh()
  }

  return (
    <form onSubmit={onSubmit} className="space-y-3" noValidate>
      <div className="space-y-2">
        <Label htmlFor="phone">Phone number</Label>
        <Input
          id="phone"
          type="tel"
          placeholder="+60 12-345 6789"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          aria-invalid={Boolean(error)}
        />
        {error && <p className="text-sm text-destructive">{error}</p>}
      </div>
      <Button type="submit" variant="outline" className="w-full" disabled={pending}>
        {pending ? 'Saving…' : 'Save phone number'}
      </Button>
    </form>
  )
}

